package sohal.lld.battleship.firing;import sohal.lld.battleship.model.Coord;import java.util.Set;public interface FireStrategy {    /**     * Pick a coordinate to fire at, given the available columns x range and already fired coords.     * Implementations must return a coordinate within [xStart..xEnd] x [0..N-1] or null if none available.     */    Coord pickTarget(int xStart, int xEnd, int n, Set<Coord> firedSoFar);}